QVDASHBOARD.JSPAGESCRIPT:
window.efXmlTextContent = null;
window.efSeftTextContent = null;
window.efSaxonTextContent = null;
window.efInvoiceId = "Neznáme";

function skontrolujStav() {
    if (window.efXmlTextContent && window.efSeftTextContent && window.efSaxonTextContent) {
        $("#btnPreview").prop("disabled", false);
        $("#btnSaveDb").prop("disabled", false);
    }
}

// 1. Výber SaxonJS knižnice z disku
function vybratSaxon() {
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = ".js,.rt";
    fileInput.onchange = (e) => {
        const file = e.target.files[0];
        if (!file) return;
        $("#saxon-info").text("SaxonJS: " + file.name);
        const reader = new FileReader();
        reader.onload = (event) => {
            window.efSaxonTextContent = event.target.result;
            // Injektujeme kód do stránky
            const scriptEl = document.createElement("script");
            scriptEl.textContent = window.efSaxonTextContent;
            document.head.appendChild(scriptEl);
            skontrolujStav();
        };
        reader.readAsText(file);
    };
    fileInput.click();
}

// 2. Výber SEF šablóny
function vybratSEF() {
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = ".sef,.json";
    fileInput.onchange = (e) => {
        const file = e.target.files[0];
        if (!file) return;
        $("#sef-info").text("Šablóna: " + file.name);
        const reader = new FileReader();
        reader.onload = (event) => {
            window.efSeftTextContent = event.target.result;
            skontrolujStav();
        };
        reader.readAsText(file);
    };
    fileInput.click();
}

// 3. Výber XML faktúry
function vybratXML() {
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = ".xml";
    fileInput.onchange = (e) => {
        const file = e.target.files[0];
        if (!file) return;
        $("#file-info").text("Faktúra: " + file.name);
        const reader = new FileReader();
        reader.onload = (event) => {
            window.efXmlTextContent = event.target.result;
            try {
                const parser = new DOMParser();
                const xmlDoc = parser.parseFromString(window.efXmlTextContent, "application/xml");
                if (xmlDoc.getElementsByTagName("parsererror").length > 0) throw new Error("Nevalidné XML");

                const idNode = xmlDoc.getElementsByTagNameNS("*", "ID")[0];
                window.efInvoiceId = idNode ? idNode.textContent : "Neznáme";
                skontrolujStav();
            } catch (err) {
                alert("Chyba pri parsovaní XML.");
                window.efXmlTextContent = null;
                $("#btnPreview, #btnSaveDb").prop("disabled", true);
            }
        };
        reader.readAsText(file);
    };
    fileInput.click();
}

// 4. Zobrazenie náhľadu
async function zobrazitNahlad() {
    if (!window.efXmlTextContent || !window.efSeftTextContent || typeof SaxonJS === "undefined") {
        alert("Musíte vybrať SaxonJS, SEF šablónu aj XML faktúru.");
        return;
    }

    try {
        const sefObjekt = JSON.parse(window.efSeftTextContent);

        const result = await SaxonJS.transform({
            stylesheetInternal: sefObjekt,
            sourceText: window.efXmlTextContent,
            destination: "serialized"
        }, "async");

        let resultHtml = "";
        if (result.principalResult) {
            resultHtml = result.principalResult;
        } else if (typeof result === "string") {
            resultHtml = result;
        }

        const previewFrame = document.getElementById("preview-window");
        if (previewFrame && previewFrame.contentWindow) {
            const frameDoc = previewFrame.contentWindow.document;
            frameDoc.open();
            frameDoc.write(resultHtml);
            frameDoc.close();
        }

    } catch (e) {
        console.error("Chyba SaxonJS transformácie:", e);
        alert("Chyba pri spracovaní šablóny: " + e.message);
    }
}

async function ulozitDoSQL() {
    if (!window.efXmlTextContent) return;
    alert("Faktúra " + window.efInvoiceId + " pripravená na zápis do DB.");
}

QVQUERY.CSSSTYLE:
.efaktura-wrapper { 
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; 
    display: flex; 
    height: 100%;
    min-height: 600px;
}
#sidebar { 
    width: 250px; 
    padding: 20px; 
    background: #eee; 
}
#sidebar button { 
    padding: 10px; 
    width: 100%; 
    margin-bottom: 10px; 
    cursor: pointer; 
}
#main-content { 
    flex: 1; 
    padding: 20px; 
    overflow-y: auto; 
}
#preview-window { 
    border: 1px solid #999; 
    height: 80vh; 
    width: 100%; 
    background: white; 
}
